<script>
const QUESTIONS = [
  { q:"Melyik ország fővárosán halad át a Duna?", a:["Prága","Bécs","Budapest","Belgrád"], c:2 },
  { q:"Hány országon halad át a Duna?", a:["7","9","10","12"], c:2 },
  { q:"Melyik országban ered a Duna?", a:["Ausztria","Svájc","Németország","Szlovákia"], c:2 },
  { q:"Melyik tengerbe ömlik a Duna?", a:["Balti-tenger","Fekete-tenger","Adria","Északi-tenger"], c:1 },
  { q:"Melyik a Duna leghosszabb magyarországi mellékfolyója?", a:["Tisza","Dráva","Rába","Sajó"], c:1 },
  { q:"Melyik város híres a Duna kettéhasításáról, ahol a folyó elválasztja a hegyeket?", a:["Belgrád","Bécs","Bratislava","Győr"], c:0 },
  { q:"Melyik magyar fővároson halad át a Duna?", a:["Debrecen","Szeged","Budapest","Pécs"], c:2 },
  { q:"Melyik a Duna torkolatvidékét alkotó ország?", a:["Ukrajna","Románia","Moldova","Görögország"], c:1 },
  { q:"Melyik a Duna legismertebb magyarországi hídja?", a:["Szabadság híd","Erzsébet híd","Margit híd","Lánchíd"], c:3 },
  { q:"Melyik a Duna teljes hossza megközelítőleg?", a:["1500 km","2000 km","2850 km","3500 km"], c:2 }
];

const KEY = "duna-quiz-v1";
const state = { idx:0, answers:Array(QUESTIONS.length).fill(null), phase:"start" };

const el = id => document.getElementById(id);
const live = el("live");
const screens = { start:el("screen-start"), q:el("screen-q"), result:el("screen-result") };

async function load() {
  try {
    if (window.alfy && window.alfy.storage) {
      const s = await window.alfy.storage.get(KEY);
      if (s && Array.isArray(s.answers) && s.answers.length === QUESTIONS.length) {
        state.answers = s.answers;
        state.idx = Number(s.idx) || 0;
        state.phase = s.phase || "start";
      }
    }
  } catch (e) {}
  render();
}

async function save() {
  try {
    if (window.alfy && window.alfy.storage) {
      await window.alfy.storage.set(KEY, { idx:state.idx, answers:state.answers, phase:state.phase });
    }
  } catch (e) {}
}

function showScreen(name) {
  for (const k in screens) screens[k].classList.toggle("hidden", k !== name);
}

function render() {
  if (state.phase === "start") { showScreen("start"); return; }
  if (state.phase === "result") { renderResult(); showScreen("result"); return; }
  renderQuestion();
  showScreen("q");
}

function renderQuestion() {
  const i = state.idx, item = QUESTIONS[i];
  el("counter").textContent = (i + 1) + " / " + QUESTIONS.length;
  el("bar-fill").style.width = ((i + 1) / QUESTIONS.length * 100) + "%";
  el("q-text").textContent = item.q;

  const opts = el("opts");
  opts.textContent = "";
  item.a.forEach((text, j) => {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "opt" + (state.answers[i] === j ? " sel" : "");
    const mark = document.createElement("span");
    mark.className = "mark";
    mark.textContent = state.answers[i] === j ? "✓" : "";
    const label = document.createElement("span");
    label.textContent = text;
    b.append(mark, label);
    b.addEventListener("click", () => choose(j));
    opts.appendChild(b);
  });

  const next = el("next-btn");
  const last = i === QUESTIONS.length - 1;
  next.textContent = last ? "Eredmény megjelenítése" : "Következő kérdés";
  next.disabled = state.answers[i] === null;
  el("back-btn").disabled = i === 0;
}

function choose(j) {
  state.answers[state.idx] = j;
  renderQuestion();
  save();
}

function next() {
  if (state.answers[state.idx] === null) return;
  if (state.idx < QUESTIONS.length - 1) {
    state.idx++;
    renderQuestion();
    save();
    announce("Kérdés " + (state.idx + 1));
  } else {
    state.phase = "result";
    render();
    save();
  }
}

function back() {
  if (state.idx > 0) {
    state.idx--;
    renderQuestion();
    save();
  }
}

function score() {
  return state.answers.reduce((n, a, i) => n + (a === QUESTIONS[i].c ? 1 : 0), 0);
}

function renderResult() {
  const s = score(), total = QUESTIONS.length;
  el("score-big").textContent = s + " / " + total;
  let msg;
  if (s === total) msg = "Tökéletes! A Duna szakértője vagy.";
  else if (s >= 7) msg = "Nagyon jól ment!";
  else if (s >= 4) msg = "Nem rossz, de még van mit tanulni.";
  else msg = "Kezdő vagy a Duna témájában – érdemes újrakezdeni.";
  el("score-line").textContent = msg;

  const ul = el("review");
  ul.textContent = "";
  QUESTIONS.forEach((item, i) => {
    const li = document.createElement("li");
    const rq = document.createElement("div");
    rq.className = "rq";
    rq.textContent = (i + 1) + ". " + item.q;
    li.appendChild(rq);

    const user = item.a[state.answers[i]];
    const ra = document.createElement("div");
    const ok = state.answers[i] === item.c;
    ra.className = "ra " + (ok ? "ok" : "bad");
    ra.textContent = (ok ? "✓ " : "✗ ") + "A te válaszod: " + user;
    li.appendChild(ra);

    if (!ok) {
      const rr = document.createElement("div");
      rr.className = "ra ok";
      rr.textContent = "Helyes válasz: " + item.a[item.c];
      li.appendChild(rr);
    }
    ul.appendChild(li);
  });
  announce("Eredmény: " + s + " a " + total + " kérdésből.");
}

function announce(t) { live.textContent = t; }

function start() {
  state.idx = 0;
  state.answers = Array(QUESTIONS.length).fill(null);
  state.phase = "q";
  render();
  save();
  announce("A kvíz elkezdődött.");
}

function restart() {
  state.idx = 0;
  state.answers = Array(QUESTIONS.length).fill(null);
  state.phase = "q";
  render();
  save();
  announce("Újrakezdés.");
}

el("start-btn").addEventListener("click", start);
el("next-btn").addEventListener("click", next);
el("back-btn").addEventListener("click", back);
el("restart-btn").addEventListener("click", restart);

load();
</script>
</body>
